function sendSlackMessage(text, channel) {
  const webhookUrl = "https://hooks.slack.com/services/T0123456789/B0123456789/XXXXXXXXXXX"; // replace with your actual Webhook URL

  const payload = {
    text: text,
    channel: channel,
  };

  fetch(webhookUrl, {
    method: "POST",
    body: JSON.stringify(payload),
    headers: {
      "Content-type": "application/json; charset=UTF-8",
    },
  })
    .then((response) => response.json())
    .then((data) => console.log("Slack message sent successfully:", data))
    .catch((error) => console.error("Error sending Slack message:", error));
}
```

To use this function, pass the message text and the channel ID (or name, if you prefer) to it:

```javascript
sendSlackMessage("Hello, world! ", "#general");
```

This will send the message to the specified channel using the provided Webhook URL. You can adjust the `webhookUrl`, `text`, and `channel` parameters to suit your needs. Note that you'll need to replace the placeholder Webhook URL with your own, which you can obtain from the Slack app settings or by creating a new Webhook Integration.

