export class Address {
  @Prop()
  street: string;

  @Prop()
  city: string;

  @Prop()
  state: string;

  @Prop()
  zip: number;
}

@Document()
export class Person {
  @Prop({ required: true })
  name: string;

  @Prop({ required: true })
  email: string;

  @Prop({ type: [Address], default: [] })
  addresses: Address[];
}

export const PersonSchema = SchemaFactory.createForClass(Person);
```

