// Recursive function to calculate Fibonacci series
int fibonacci(int n, int a, int b) {
    if (n == 1)
        return a;
    else
        return fibonacci(n - 1, b, a + b);
}

int main() {
    std::string input;
    int first, second, numElements;

    // Prompt user for first two elements
    std::cout << "Enter the first two elements of the Fibonacci series: ";
    std::getline(std::cin, input);
    std::istringstream iss(input);

    try {
        iss >> first >> second;

        // Check for valid inputs
        if (first <= 0 || second <= 0)
            throw std::runtime_error("First and second elements must be positive integers.");
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return 1;
    }

    // Prompt user for number of elements
    std::cout << "Enter the number of elements in the Fibonacci series: ";
    std::cin >> numElements;

    // Check for valid input
    if (numElements <= 0)
        throw std::runtime_error("Number of elements must be a positive integer.");

    // Generate Fibonacci series
    int result = fibonacci(numElements, first, second);

    // Output generated series
    std::cout << "Fibonacci series: ";
    for (int I = 1; I <= numElements; ++i) {
        std::cout << result << (i != numElements ? ", " : "");
        result = fibonacci(i, second, first + second);
    }

    return 0;
}
```

