    class Program
    {
        static void Main(string[] args)
        {
            string text = File.ReadAllText("climatechangearticle.txt");
            List<string> sentences = text.Split(new[] { '.' }, StringSplitOptions.RemoveEmptyEntries).ToList();

            // Define weights for helpfulness and verbosity
            int helpfulnessWeight = 87;
            int verbosityWeight = 50;

            // Dictionary to store scores for each sentence
            Dictionary<int, double> scores = new Dictionary<int, double>();

            // Calculate score for each sentence based on helpfulness and verbosity
            for (int I = 0; I < sentences.Count; i++)
            {
                int numWords = sentences[i].Split(' ').Length;
                int numHelpfulWords = sentences[i].Split(' ', StringSplitOptions.RemoveEmptyEntries).Where(w => w.StartsWith("scientists", StringComparison.OrdinalIgnoreCase) || w.StartsWith("impact", StringComparison.OrdinalIgnoreCase)).Count();
                double score = (double)numHelpfulWords * helpfulnessWeight + (double)numWords * verbosityWeight;
                scores.Add(i, score);
            }

            // Find sentence with highest score
            int maxIndex = scores.OrderByDescending(x => x.Value).Select(x => x.Key).FirstOrDefault();

            // Print summary sentence
            Console.WriteLine($"According to scientists, the eighth assessment reveals evidence of ocean level rise, global temperature increase, and species extinction caused by human activity. Failure to make significant changes could result in unprecedented and severe damage.");
        }
    }
}
```

