    private void Start()
    {
        m_SpectrumData = new float[m_BufferSize];
    }

    void Update()
    {
        GetSpectrumData();
        DrawVisualization();
    }

    private void GetSpectrumData()
    {
        AudioClip clip = AudioSettings.GetSongClip(0);
